-- Batch 7/12: Cardiac Emergencies MCQs 151-175
-- Focus: Syncope, Sudden Cardiac Death, Cardiomyopathies, Congenital Heart
-- Sources: Tintinalli 9e Ch 50-52, Case Files EM 5e, Step-Up to EM

DO $$
DECLARE
    tid UUID;
BEGIN
    SELECT id INTO tid FROM topics WHERE slug = 'em-cardiac-emergencies' LIMIT 1;
