    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (tid, '151. A 19-year-old basketball player collapses on the court and is found in cardiac arrest. What is the most common cause of sudden cardiac death in young athletes?', '["Coronary artery disease", "Hypertrophic cardiomyopathy (HCM)", "Long QT syndrome", "Commotio cordis"]', 1, 'HCM is the leading cause of sudden cardiac death in athletes <35 years in the US. It causes asymmetric septal hypertrophy leading to dynamic LVOT obstruction and lethal arrhythmias during exertion.'),
    (tid, '152. Which ECG finding is characteristic of hypertrophic cardiomyopathy?', '["Diffuse ST elevation", "LVH with deep septal Q waves (dagger Q) in lateral leads and asymmetric T-wave inversions", "Short PR with delta waves", "Low voltage QRS"]', 1, 'HCM shows LVH voltage criteria, deep narrow Q waves in lateral and inferior leads (septal hypertrophy), and asymmetric T-wave inversions. These findings may mimic an old MI pattern.'),
    (tid, '153. What maneuver increases the murmur of hypertrophic obstructive cardiomyopathy (HOCM)?', '["Squatting", "Leg elevation", "Valsalva maneuver (decreases preload)", "Hand grip"]', 2, 'HOCM murmur increases with anything that decreases preload or LV volume (Valsalva, standing, dehydration) because the septum and mitral leaflet are brought closer together, worsening obstruction.'),
    (tid, '154. In the ED, how should acute LVOT obstruction in HOCM with hypotension be managed?', '["IV dobutamine", "IV fluids, phenylephrine, and beta-blockers; AVOID inotropes and vasodilators", "Nitroglycerin", "Intra-aortic balloon pump"]', 1, 'HOCM with dynamic obstruction requires volume loading (IV fluids), vasoconstriction (phenylephrine), and negative inotropy (beta-blockers). Inotropes, diuretics, and vasodilators worsen obstruction.'),
    (tid, '155. A 16-year-old is hit in the chest by a baseball and immediately collapses in VF. What is this phenomenon called?', '["Cardiac contusion", "Commotio cordis", "Cardiac tamponade", "Aortic rupture"]', 1, 'Commotio cordis is VF triggered by a blunt precordial impact during the vulnerable repolarization phase (just before the T-wave peak). It occurs in young athletes with compliant chest walls. Treatment: immediate defibrillation.'),
    (tid, '156. A patient presents with syncope. Which feature suggests a cardiac etiology rather than vasovagal?', '["Syncope preceded by prolonged standing", "Syncope during exertion or while supine", "Associated with nausea and diaphoresis", "Gradual onset with prodrome"]', 1, 'Exertional syncope or syncope while supine/during sleep is high-risk and suggests a cardiac cause (arrhythmia, structural heart disease, HOCM). Vasovagal syncope has a prodrome with standing/emotional triggers.'),
    (tid, '157. What is the San Francisco Syncope Rule used for?', '["Diagnosing the cause of syncope", "Identifying patients at short-term risk for serious outcomes after syncope", "Determining need for pacemaker", "Classifying arrhythmia severity"]', 1, 'The San Francisco Syncope Rule (CHESS: CHF history, Hematocrit <30%, ECG abnormal, Shortness of breath, Systolic BP <90) identifies syncope patients at risk for serious 30-day outcomes requiring admission.'),
    (tid, '158. A 25-year-old presents with syncope. ECG shows a "coved-type" ST elevation in V1-V3 with RBBB pattern. What syndrome does this suggest?', '["WPW syndrome", "Brugada syndrome", "Long QT syndrome", "Early repolarization"]', 1, 'Brugada syndrome shows coved ST elevation (≥2mm) in V1-V3 with RBBB morphology (Type 1 pattern). It causes VF and sudden death, often during sleep. Treatment: ICD. Avoid fever, which can unmask the pattern.'),
    (tid, '159. A patient with known Brugada syndrome presents with fever of 39.5°C. Why is this dangerous?', '["Fever causes dehydration", "Fever can unmask or exacerbate the Brugada ECG pattern and trigger VF", "Fever causes hyperkalemia", "Fever worsens heart failure"]', 1, 'Fever upregulates the dysfunctional sodium channels in Brugada syndrome, exacerbating the ECG pattern and increasing VF risk. Aggressive antipyretic treatment is essential. Admit for monitoring.'),
    (tid, '160. Which inherited channelopathy is associated with exercise-induced polymorphic VT, particularly during swimming or emotional stress?', '["Brugada syndrome", "Catecholaminergic polymorphic VT (CPVT)", "Long QT type 1", "Short QT syndrome"]', 1, 'CPVT is caused by RyR2 or CASQ2 mutations causing abnormal calcium release during adrenergic stimulation. It produces bidirectional VT during exercise or stress. Beta-blockers are first-line; ICD for refractory cases.'),
    (tid, '161. A young patient with syncope has a QTc of 520 ms on ECG. What is the diagnosis and what activities must be restricted?', '["Brugada syndrome; restrict sleep", "Long QT syndrome; restrict competitive sports and avoid QT-prolonging drugs", "WPW; restrict caffeine", "HCM; restrict weightlifting"]', 1, 'Long QT syndrome (QTc >470ms males, >480ms females) predisposes to Torsades de Pointes and sudden death. Avoid QT-prolonging drugs, competitive sports, and correct electrolytes. Beta-blockers reduce risk.'),
    (tid, '162. Which type of Long QT syndrome is triggered by auditory stimuli (e.g., alarm clocks)?', '["LQT1", "LQT2", "LQT3", "LQT5"]', 1, 'LQT2 (HERG/KCNH2 mutation) is triggered by sudden auditory stimuli and emotional stress. LQT1 is triggered by exercise (especially swimming). LQT3 events occur at rest or during sleep.'),
    (tid, '163. Arrhythmogenic right ventricular cardiomyopathy (ARVC) is characterized by which pathological finding?', '["LV hypertrophy", "Fibrofatty replacement of RV myocardium", "Amyloid deposits", "Myxomatous valve degeneration"]', 1, 'ARVC involves progressive fibrofatty replacement of RV myocardium, creating a substrate for re-entrant VT. ECG shows epsilon waves, T-wave inversions in V1-V3. It is a cause of sudden death in young athletes.'),
    (tid, '164. What ECG finding is specific to ARVC?', '["Delta waves", "Epsilon waves (small deflections at the end of QRS in V1-V3)", "Osborn waves", "U waves"]', 1, 'Epsilon waves are small post-QRS potentials in V1-V3 representing delayed RV activation through fibrofatty tissue. They are present in ~30% of ARVC patients and are pathognomonic when found.'),
    (tid, '165. Takotsubo cardiomyopathy (stress cardiomyopathy) typically presents in which demographic?', '["Young male athletes", "Postmenopausal women after emotional or physical stress", "Neonates", "Elderly men with coronary disease"]', 1, 'Takotsubo predominantly affects postmenopausal women after intense emotional or physical stress. It mimics STEMI with apical ballooning on echo but has clean coronaries on angiography. Most recover fully.'),
    (tid, '166. On ventriculography or echo, what is the classic finding in Takotsubo cardiomyopathy?', '["Global hypokinesis", "Apical ballooning with basal hyperkinesis (inverted tako-tsubo shape)", "Septal hypertrophy", "RV dilation"]', 1, 'The apical ballooning pattern with compensatory basal hyperkinesis creates the classic "takotsubo" (Japanese octopus trap) shape. It results from catecholamine-mediated myocardial stunning.'),
    (tid, '167. A neonate presents with cyanosis unresponsive to supplemental oxygen. Hyperoxia test shows PaO2 remains below 70 mmHg on 100% FiO2. What does this suggest?', '["Pneumonia", "Cyanotic congenital heart disease", "Persistent pulmonary hypertension", "Meconium aspiration"]', 1, 'A failed hyperoxia test (PaO2 <70 mmHg on 100% O2) strongly suggests a fixed right-to-left cardiac shunt from cyanotic congenital heart disease (e.g., Tetralogy of Fallot, TGA, truncus arteriosus).'),
    (tid, '168. A 3-month-old with known Tetralogy of Fallot becomes acutely cyanotic and irritable during crying. What is this episode called and what is the immediate treatment?', '["Seizure; give diazepam", "Tet spell (hypercyanotic spell); knee-to-chest position, morphine, oxygen, phenylephrine", "Bronchospasm; give albuterol", "Heart failure; give furosemide"]', 1, 'Tet spells are caused by acute increase in RV outflow obstruction and right-to-left shunting. Knee-to-chest position increases SVR, reducing the shunt. Morphine calms, phenylephrine increases SVR, oxygen helps.'),
    (tid, '169. Which congenital heart defect requires prostaglandin E1 (PGE1) infusion to maintain patency of the ductus arteriosus?', '["Atrial septal defect", "Ductal-dependent lesions (critical coarctation, hypoplastic left heart, transposition of great arteries)", "Ventricular septal defect", "Patent foramen ovale"]', 1, 'PGE1 maintains ductal patency in neonates with ductal-dependent lesions where systemic or pulmonary blood flow depends on the PDA. Side effects: apnea (have intubation equipment ready), hypotension, fever.'),
    (tid, '170. A previously healthy infant presents at 2 weeks of age with poor feeding, tachypnea, hepatomegaly, and a gallop rhythm. CXR shows cardiomegaly. What is the most likely diagnosis?', '["Bronchiolitis", "Congenital heart failure from a structural defect (e.g., critical coarctation, large VSD)", "Sepsis", "Pyloric stenosis"]', 1, 'CHF in neonates presenting at 1-3 weeks often indicates a ductal-dependent lesion or large left-to-right shunt becoming symptomatic as pulmonary vascular resistance drops. Evaluate with echo and start PGE1 if ductal-dependent.'),
    (tid, '171. What is the most common congenital heart defect overall?', '["Atrial septal defect", "Ventricular septal defect", "Patent ductus arteriosus", "Tetralogy of Fallot"]', 1, 'VSD is the most common congenital heart defect, accounting for 25-30% of all CHD. Most small VSDs close spontaneously. Large VSDs cause heart failure from left-to-right shunting and require surgical repair.'),
    (tid, '172. A child with Down syndrome is found to have an endocardial cushion defect. What is the most common associated cardiac anomaly?', '["Tetralogy of Fallot", "Atrioventricular septal defect (AVSD / AV canal defect)", "Coarctation of the aorta", "Transposition of great arteries"]', 1, 'AVSD (complete AV canal) is strongly associated with Trisomy 21 (Down syndrome), occurring in ~40% of DS patients with CHD. It involves defects in both the atrial and ventricular septa with a common AV valve.'),
    (tid, '173. Coarctation of the aorta classically presents with which physical finding?', '["Bounding pulses in all extremities", "Upper extremity hypertension with diminished or absent femoral pulses", "Wide pulse pressure", "Pulsus paradoxus"]', 1, 'Coarctation (typically juxtaductal) causes a BP gradient between upper and lower extremities. Upper extremity HTN with weak/absent femoral pulses and a systolic murmur at the left interscapular area are classic.'),
    (tid, '174. A patient with Turner syndrome (45,XO) should be screened for which cardiac condition?', '["Mitral valve prolapse", "Bicuspid aortic valve and coarctation of the aorta", "Ebstein anomaly", "Tetralogy of Fallot"]', 1, 'Turner syndrome is associated with bicuspid aortic valve (30%) and coarctation of the aorta (10-20%). Aortic root dilation and dissection are also increased, requiring lifelong cardiovascular surveillance.'),
    (tid, '175. A patient with Marfan syndrome has a dilated aortic root measuring 5.2 cm. At what threshold is prophylactic surgical repair recommended?', '["3.0 cm", "4.0 cm", "5.0 cm (or 4.5 cm with risk factors)", "6.0 cm"]', 2, 'Prophylactic aortic root replacement in Marfan syndrome is recommended at ≥5.0 cm, or ≥4.5 cm with risk factors (family history of dissection, rapid growth >0.5 cm/year, severe aortic regurgitation).');
